<dialog id="login-dialog" class="login-dialog" aria-labelledby="login-title"><div class="login-shell"><button type="button" class="login-close" data-login-close aria-label="Schließen">×</button><img class="login-logo" src="data:image/png;base64," alt="Pflegerouter Logo"><span class="eyebrow">DEIN PFLEGEROUTER</span><h2 id="login-title">Willkommen zurück.</h2><p>Melde dich in deinem persönlichen Bereich an.</p><form id="login-form" method="POST" action="/login"><label for="login-email">E-Mail-Adresse</label><input id="login-email" name="email" type="email" autocomplete="username" placeholder="name@beispiel.de" required><label for="login-password">Passwort</label><div class="password-wrap"><input id="login-password" name="password" type="password" autocomplete="current-password" placeholder="Passwort eingeben" required><button type="button" id="password-toggle" aria-label="Passwort anzeigen">Anzeigen</button></div><button type="submit" class="login-submit">Anmelden <span>→</span></button></form><div id="login-message" role="status" aria-live="polite"></div><p class="login-disclaimer">Die Anmeldung erfolgt sicher über deinen Pflegerouter-Zugang.</p></div></dialog><script>
const toggle=document.querySelector('.menu-toggle');const links=document.querySelector('.nav-links');toggle?.addEventListener('click',()=>{const open=links.classList.toggle('open');toggle.setAttribute('aria-expanded',String(open));toggle.setAttribute('aria-label',open?'Menü schließen':'Menü öffnen');toggle.textContent=open?'×':'☰'});document.querySelectorAll('.nav-links a').forEach(a=>a.addEventListener('click',()=>{links.classList.remove('open');toggle.setAttribute('aria-expanded','false');toggle.textContent='☰'}));document.getElementById('year').textContent=new Date().getFullYear();
const dialog=document.getElementById('login-dialog');document.querySelectorAll('[data-login-open]').forEach(b=>b.addEventListener('click',()=>{dialog.showModal();document.getElementById('login-email').focus()}));document.querySelector('[data-login-close]').addEventListener('click',()=>dialog.close());dialog.addEventListener('click',e=>{if(e.target===dialog)dialog.close()});document.getElementById('password-toggle').addEventListener('click',e=>{const input=document.getElementById('login-password');const showing=input.type==='password';input.type=showing?'text':'password';e.currentTarget.textContent=showing?'Verbergen':'Anzeigen';e.currentTarget.setAttribute('aria-label',showing?'Passwort verbergen':'Passwort anzeigen')});

</script></body></html>
